// Physics constants
const GRAVITY = 9.81; // m/s^2
const MASS_OF_PENDULUM = 1; // kg
const LENGTH_OF_PENDULUM = 1; // m

// Render the pendulum canvas
let canvas = document.getElementById("pendulum");
let ctx = canvas.getContext("2d");
canvas.width = 200;
canvas.height = 200;

// Initialize the pendulum's angle and velocity
let initialAngle = 0;
let angle = 0;
let velocity = 0;

// Function to update the pendulum's state using physics
function updatePendulum() {
  // Calculate the acceleration due to gravity
  let acceleration = -GRAVITY * Math.sin(Math.PI / 180 * angle);

  // Update the velocity and angle using the equations of motion
  velocity += acceleration * (1 / MASS_OF_PENDULUM);
  angle += velocity / (LENGTH_OF_PENDULUM * 2 * Math.PI) * 360;

  // Constrain the angle to be within the range 0-360 degrees
  if (angle < 0) {
    angle += 360;
  } else if (angle > 360) {
    angle -= 360;
  }
}

// Function to draw the pendulum on the canvas
function drawPendulum() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, LENGTH_OF_PENDULUM * Math.sin(Math.PI / 180 * angle), canvas.width / 2, canvas.height / 2);
  ctx.fillStyle = "black";
  ctx.fill();
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 5, canvas.width / 2, canvas.height / 2);
  ctx.fillStyle = "red";
  ctx.fill();
}

// Main loop to update and draw the pendulum
function loop() {
  updatePendulum();
  drawPendulum();

  // Check if the pendulum has stopped swinging
  if (Math.abs(velocity) < 0.01) {
    velocity = 0;
    angle = initialAngle;
  }

  requestAnimationFrame(loop);
}

// Event listener for the release button
document.getElementById("release-button").addEventListener("click", () => {
