			continue
		}

		// Get snapshot creation time
		creationTime := snapshot.StartTime.Unix()

		// Get all snapshots with same tag value and creation time
		otherSnapshots := getSnapshotsWithTagValueAndCreationTime(tag, creationTime, ec2Client)

