#include <pigpio.h>

#define PIN 12 // GPIO pin 12

int main() {
    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        std::cerr << "pigpio initialization failed" << std::endl;
        return 1;
    }

    // Set pin 12 as an output
    gpioSetup(PIN, PWM_OUTPUT);

    // Set initial value of pin 12 to LOW (0V)
    gpioWrite(PIN, PI_LOW);

    while (true) {
        // Set pin 12 to HIGH (3.3V)
        gpioWrite(PIN, PI_HIGH);
        delay(1000); // wait for 1 second

        // Set pin 12 to LOW (0V)
        gpioWrite(PIN, PI_LOW);
        delay(1000); // wait for 1 second
    }

    // Clean up
    gpioTerminate();
    return 0;
}
```
