import { Layout } from 'next/font';
import Navbar from '../components/Navbar';

function MyApp({ Component, pageProps }) {
  const [showNavbar, setShowNavbar] = useState(true);

  return (
    <Layout>
      {showNavbar && <Navbar />}
      <Component {...pageProps} />
    </Layout>
  );
}

MyApp.getLayout = function getLayout(getPageProps) {
  return async function getLayout(props) {
    const { pathname } = props.router;
    const ignorePaths = ['/404', '/explicitly-ignore-path'];

    if (!ignorePaths.includes(pathname) && pathname !== '/404') {
      setShowNavbar(true);
    } else {
      setShowNavbar(false);
    }

    return <MyApp {...props} />;
  };
};

export default MyApp;
